import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { createContractProcedureBuilder } from "../errors";

// Academic score constants
const MIN_SCORE = 0;
const MAX_GPA_UNWEIGHTED = 4;
const MAX_GPA_WEIGHTED = 5;
const MAX_PERCENTILE = 100;
const MIN_PERCENTILE = 0;

// Test score constants
const SAT_MIN_TOTAL = 400;
const SAT_MAX_TOTAL = 1600;
const SAT_MIN_SECTION = 200;
const SAT_MAX_SECTION = 800;
const ACT_MIN_SCORE = 1;
const ACT_MAX_SCORE = 36;

// Probability constants
const MIN_PROBABILITY = 0;
const MAX_PROBABILITY = 1;
const MAX_SCORE_10 = 10;
const _MIN_DATA_YEAR = 1900;
const _MAX_DATA_YEAR = 3000;
const _MAX_SCORECARD_CHUNK_SIZE = 50_000;
const MAX_FIXTURE_LIST_LIMIT = 100;
const ENRICHMENT_ATTEMPT_STATUSES = [
  "pending",
  "success",
  "partial",
  "failed",
  "skipped",
] as const;

const ADMISSION_LABELS = ["REACH", "TARGET", "LIKELY", "SAFETY"] as const;
export const AdmissionLabelSchema = z.enum(ADMISSION_LABELS);
export type AdmissionLabel = (typeof ADMISSION_LABELS)[number];

const TEST_POLICY_VALUES = ["REQUIRED", "OPTIONAL", "NOT_CONSIDERED"] as const;
export const TestPolicySchema = z.enum(TEST_POLICY_VALUES);
export type TestPolicy = (typeof TEST_POLICY_VALUES)[number];

const TEST_INTENT_VALUES = ["SUBMIT", "NO_SCORE"] as const;
export const TestIntentSchema = z.enum(TEST_INTENT_VALUES);
export type TestIntent = (typeof TEST_INTENT_VALUES)[number];
export const enrichmentAttemptStatusSchema = z.enum(
  ENRICHMENT_ATTEMPT_STATUSES,
);
export type EnrichmentAttemptStatus =
  (typeof ENRICHMENT_ATTEMPT_STATUSES)[number];

const US_STATE_TERRITORY_CODES = [
  "AL",
  "AK",
  "AZ",
  "AR",
  "CA",
  "CO",
  "CT",
  "DE",
  "FL",
  "GA",
  "HI",
  "ID",
  "IL",
  "IN",
  "IA",
  "KS",
  "KY",
  "LA",
  "ME",
  "MD",
  "MA",
  "MI",
  "MN",
  "MS",
  "MO",
  "MT",
  "NE",
  "NV",
  "NH",
  "NJ",
  "NM",
  "NY",
  "NC",
  "ND",
  "OH",
  "OK",
  "OR",
  "PA",
  "RI",
  "SC",
  "SD",
  "TN",
  "TX",
  "UT",
  "VT",
  "VA",
  "WA",
  "WV",
  "WI",
  "WY",
  "DC",
  "PR",
  "GU",
  "VI",
  "AS",
  "MP",
  "AA",
  "AE",
  "AP",
  "FM",
  "MH",
  "PW",
] as const;

export const stateCodeSchema = z.enum(US_STATE_TERRITORY_CODES);

type UnitIdBrand = { readonly unitId: unique symbol };
export type UnitId = number & UnitIdBrand;
export const unitIdSchema = z
  .number()
  .int()
  .nonnegative()
  .transform((value) => value as UnitId);

export const studentIdSchema = z.string().cuid2();

const contractProcedure = createContractProcedureBuilder();

export const enrichmentSourceSchema = z
  .object({
    url: z.string().url(),
    note: z.string().max(400).optional(),
  })
  .strict();

export const universityEnrichmentTargetFieldSchema = z.enum([
  "avgAdmitGpa4",
  "admitRates",
  "residencySplit",
  "c7Weights",
  "latestYear",
  "testPolicy",
]);
export type UniversityEnrichmentTargetField = z.infer<
  typeof universityEnrichmentTargetFieldSchema
>;

const factorWeightSchema = z.enum([
  "VERY",
  "IMPORTANT",
  "CONSIDERED",
  "NOT_CONSIDERED",
]);
const c7ImportanceSchema = factorWeightSchema;
const testPolicySchema = TestPolicySchema;
const testIntentSchema = TestIntentSchema;

const enrichmentC7WeightsSchema = z
  .object({
    rigor: c7ImportanceSchema.nullable().optional(),
    gpa: c7ImportanceSchema.nullable().optional(),
    tests: c7ImportanceSchema.nullable().optional(),
    essay: c7ImportanceSchema.nullable().optional(),
    recs: c7ImportanceSchema.nullable().optional(),
    extracurriculars: c7ImportanceSchema.nullable().optional(),
  })
  .partial()
  .optional();

const _enrichmentMetricsSchema = z
  .object({
    avgAdmitGpa4: z
      .number()
      .min(MIN_SCORE)
      .max(MAX_GPA_UNWEIGHTED)
      .nullable()
      .optional(),
    admitRateOverall: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .nullable()
      .optional(),
    admitRateInState: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .nullable()
      .optional(),
    admitRateOutOfState: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .nullable()
      .optional(),
    residencySplitInState: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .nullable()
      .optional(),
    residencySplitOutOfState: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .nullable()
      .optional(),
    c7Weights: enrichmentC7WeightsSchema,
    testPolicy: testPolicySchema.nullable().optional(),
  })
  .strict();

const studentAcademicsContractSchema = z
  .object({
    gpaUnweighted4: z.number().min(MIN_SCORE).max(MAX_GPA_UNWEIGHTED),
    gpaWeighted5: z.number().min(MIN_SCORE).max(MAX_GPA_WEIGHTED).optional(),
    classRankPercentile: z
      .number()
      .min(MIN_PERCENTILE)
      .max(MAX_PERCENTILE)
      .optional(),
    rigorLevel01: z.number().min(MIN_SCORE).max(MAX_PROBABILITY).optional(),
    apCount: z.number().int().min(MIN_SCORE).optional(),
    ibCount: z.number().int().min(MIN_SCORE).optional(),
    honorsCount: z.number().int().min(MIN_SCORE).optional(),
  })
  .strict();

const studentTestsContractSchema = z
  .object({
    intent: testIntentSchema,
    satTotal1600: z.number().min(SAT_MIN_TOTAL).max(SAT_MAX_TOTAL).optional(),
    satEbrw: z.number().min(SAT_MIN_SECTION).max(SAT_MAX_SECTION).optional(),
    satMath: z.number().min(SAT_MIN_SECTION).max(SAT_MAX_SECTION).optional(),
    actComposite36: z
      .number()
      .int()
      .min(ACT_MIN_SCORE)
      .max(ACT_MAX_SCORE)
      .optional(),
  })
  .strict();

const studentHooksContractSchema = z
  .object({
    legacyCollegeUnitids: z.array(unitIdSchema).optional(),
    recruitedAthlete: z.boolean().optional(),
    firstGen: z.boolean().optional(),
  })
  .strict();

export const studentContractSchema = z
  .object({
    stateOfResidence: stateCodeSchema,
    academics: studentAcademicsContractSchema,
    tests: studentTestsContractSchema,
    extracurricularLevel01: z
      .number()
      .min(MIN_SCORE)
      .max(MAX_PROBABILITY)
      .optional(),
    essayQuality01: z.number().min(MIN_SCORE).max(MAX_PROBABILITY).optional(),
    recommendationStrength01: z
      .number()
      .min(MIN_SCORE)
      .max(MAX_PROBABILITY)
      .optional(),
    hooks: studentHooksContractSchema.optional(),
  })
  .strict();

const universityTestsSatSchema = z
  .object({
    composite25: z
      .number()
      .int()
      .min(SAT_MIN_TOTAL)
      .max(SAT_MAX_TOTAL)
      .optional(),
    composite75: z
      .number()
      .int()
      .min(SAT_MIN_TOTAL)
      .max(SAT_MAX_TOTAL)
      .optional(),
    ebrw25: z
      .number()
      .int()
      .min(SAT_MIN_SECTION)
      .max(SAT_MAX_SECTION)
      .optional(),
    ebrw75: z
      .number()
      .int()
      .min(SAT_MIN_SECTION)
      .max(SAT_MAX_SECTION)
      .optional(),
    math25: z
      .number()
      .int()
      .min(SAT_MIN_SECTION)
      .max(SAT_MAX_SECTION)
      .optional(),
    math75: z
      .number()
      .int()
      .min(SAT_MIN_SECTION)
      .max(SAT_MAX_SECTION)
      .optional(),
    avg: z.number().int().min(SAT_MIN_TOTAL).max(SAT_MAX_TOTAL).optional(),
  })
  .strict();

const universityTestsActSchema = z
  .object({
    comp25: z.number().int().min(ACT_MIN_SCORE).max(ACT_MAX_SCORE).optional(),
    comp75: z.number().int().min(ACT_MIN_SCORE).max(ACT_MAX_SCORE).optional(),
  })
  .strict();

const universityC7ContractSchema = z
  .object({
    rigor: factorWeightSchema.optional(),
    gpa: factorWeightSchema.optional(),
    tests: factorWeightSchema.optional(),
    essay: factorWeightSchema.optional(),
    recs: factorWeightSchema.optional(),
    extracurriculars: factorWeightSchema.optional(),
  })
  .strict();

export const universityContractSchema = z
  .object({
    unitid: unitIdSchema,
    name: z.string().min(1),
    state: stateCodeSchema,
    isPublic: z.boolean(),
    admitRateOverall: z.number().min(MIN_PROBABILITY).max(MAX_PROBABILITY),
    sat: universityTestsSatSchema.optional(),
    act: universityTestsActSchema.optional(),
    avgAdmitGpa4: z.number().min(MIN_SCORE).max(MAX_GPA_UNWEIGHTED).optional(),
    testPolicy: testPolicySchema,
    admitRateInState: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .optional(),
    admitRateOutOfState: z
      .number()
      .min(MIN_PROBABILITY)
      .max(MAX_PROBABILITY)
      .optional(),
    c7Weights: universityC7ContractSchema.optional(),
  })
  .strict();

export const modelOptionsContractSchema = z
  .object({
    k: z.number().optional(),
    gpaDiffNormalizer: z.number().optional(),
    testWeight: z.number().optional(),
    gpaWeight: z.number().optional(),
    rigorWeight: z.number().optional(),
    extracurricularWeight: z.number().optional(),
    essayWeight: z.number().optional(),
    recommendationsWeight: z.number().optional(),
    hookBoostLegacy: z.number().optional(),
    hookBoostAthlete: z.number().optional(),
    hookBoostFirstGen: z.number().optional(),
    probabilityFloor: z.number().optional(),
    probabilityCeiling: z.number().optional(),
  })
  .strict();

const chanceBreakdownContractSchema = z.record(z.string(), z.number());

export const chanceResultContractSchema = z
  .object({
    probability: z.number().min(MIN_PROBABILITY).max(MAX_PROBABILITY),
    score10: z.number().min(MIN_SCORE).max(MAX_SCORE_10),
    label: AdmissionLabelSchema,
    breakdown: chanceBreakdownContractSchema,
  })
  .strict();

const scoreOneInputContractSchema = z
  .object({
    student: studentContractSchema,
    university: universityContractSchema,
    options: modelOptionsContractSchema.optional(),
  })
  .strict();

const scoreManyInputContractSchema = z
  .object({
    student: studentContractSchema,
    universities: z.array(universityContractSchema).min(1),
    options: modelOptionsContractSchema.optional(),
  })
  .strict();

const debugBreakdownOutputSchema = z
  .object({
    inputs: scoreOneInputContractSchema,
    result: chanceResultContractSchema,
  })
  .strict();

const scoringOverrideDefaultsSchema = z
  .object({
    k: z.number(),
    probabilityFloor: z.number(),
    probabilityCeiling: z.number(),
    testWeight: z.number(),
    gpaWeight: z.number(),
    rigorWeight: z.number(),
    extracurricularWeight: z.number(),
    essayWeight: z.number(),
    recommendationsWeight: z.number(),
    hookBoostLegacy: z.number(),
    hookBoostAthlete: z.number(),
    hookBoostFirstGen: z.number(),
    gpaDiffNormalizer: z.number(),
  })
  .strict();

const scoringOverrideBoundSchema = z
  .object({
    min: z.number(),
    max: z.number(),
  })
  .strict();

const scoringOverrideBoundsSchema = z
  .object({
    k: scoringOverrideBoundSchema,
    probabilityFloor: scoringOverrideBoundSchema,
    probabilityCeiling: scoringOverrideBoundSchema,
    testWeight: scoringOverrideBoundSchema,
    gpaWeight: scoringOverrideBoundSchema,
    rigorWeight: scoringOverrideBoundSchema,
    extracurricularWeight: scoringOverrideBoundSchema,
    essayWeight: scoringOverrideBoundSchema,
    recommendationsWeight: scoringOverrideBoundSchema,
    hookBoostLegacy: scoringOverrideBoundSchema,
    hookBoostAthlete: scoringOverrideBoundSchema,
    hookBoostFirstGen: scoringOverrideBoundSchema,
    gpaDiffNormalizer: scoringOverrideBoundSchema,
  })
  .strict();

export const scoreOneContract = contractProcedure
  .input(scoreOneInputContractSchema)
  .output(chanceResultContractSchema);

export const scoreManyContract = contractProcedure
  .input(scoreManyInputContractSchema)
  .output(
    z
      .array(
        z.object({
          unitid: unitIdSchema,
          result: chanceResultContractSchema,
        }),
      )
      .min(1),
  );

const getScoringDefaultsContract = contractProcedure.output(
  z
    .object({
      defaults: scoringOverrideDefaultsSchema,
      bounds: scoringOverrideBoundsSchema,
    })
    .strict(),
);

export const debugBreakdownContract = contractProcedure
  .input(scoreOneInputContractSchema)
  .output(debugBreakdownOutputSchema);

export const admissionsContract = {
  scoreOne: scoreOneContract,
  scoreMany: scoreManyContract,
  debugBreakdown: debugBreakdownContract,
  seedFixtures: contractProcedure
    .input(
      z
        .object({
          dryRun: z.boolean().optional(),
          dataVersion: z.string().optional(),
        })
        .optional(),
    )
    .output(
      z
        .object({
          runId: z.string().uuid(),
          totals: z.object({
            universities: z.number().int().nonnegative(),
            projections: z.number().int().nonnegative(),
            students: z.number().int().nonnegative(),
          }),
          durationMs: z.number().int().nonnegative(),
          warnings: z.array(z.string()).optional(),
          dataVersion: z.string().optional(),
          scoringConfig: z
            .object({
              k: z.number().optional(),
              gpaDiffNormalizer: z.number().optional(),
              testWeight: z.number().optional(),
              gpaWeight: z.number().optional(),
              rigorWeight: z.number().optional(),
              extracurricularWeight: z.number().optional(),
              essayWeight: z.number().optional(),
              recommendationsWeight: z.number().optional(),
              hookBoostLegacy: z.number().optional(),
              hookBoostAthlete: z.number().optional(),
              hookBoostFirstGen: z.number().optional(),
              probabilityFloor: z.number().optional(),
              probabilityCeiling: z.number().optional(),
            })
            .optional(),
        })
        .strict(),
    ),
  listFixtureStudents: contractProcedure
    .input(
      z
        .object({
          limit: z.number().int().min(1).max(MAX_FIXTURE_LIST_LIMIT).optional(),
        })
        .optional(),
    )
    .output(
      z
        .object({
          items: z.array(
            z.object({
              id: studentIdSchema,
              student: studentContractSchema,
              createdAt: z.string(),
              updatedAt: z.string(),
            }),
          ),
        })
        .strict(),
    ),
  listFixtureUniversities: contractProcedure
    .input(
      z
        .object({
          limit: z.number().int().min(1).max(MAX_FIXTURE_LIST_LIMIT).optional(),
        })
        .optional(),
    )
    .output(
      z
        .object({
          items: z.array(
            z.object({
              unitid: unitIdSchema,
              university: universityContractSchema,
              updatedAt: z.string().optional(),
            }),
          ),
        })
        .strict(),
    ),
  getScoringDefaults: getScoringDefaultsContract,
};

export type AdmissionsContract = typeof admissionsContract;

export type AdmissionsContractInputs =
  InferContractRouterInputs<AdmissionsContract>;
export type AdmissionsContractOutputs =
  InferContractRouterOutputs<AdmissionsContract>;

export type ScoreOneContractInput = AdmissionsContractInputs["scoreOne"];
export type ScoreOneContractOutput = AdmissionsContractOutputs["scoreOne"];
export type ScoreManyContractInput = AdmissionsContractInputs["scoreMany"];
export type ScoreManyContractOutput = AdmissionsContractOutputs["scoreMany"];
export type DebugBreakdownContractOutput =
  AdmissionsContractOutputs["debugBreakdown"];
export type GetScoringDefaultsContractOutput =
  AdmissionsContractOutputs["getScoringDefaults"];
export type SeedFixturesContractInput =
  AdmissionsContractInputs["seedFixtures"];
export type SeedFixturesContractOutput =
  AdmissionsContractOutputs["seedFixtures"];
export type ListFixtureStudentsContractInput =
  AdmissionsContractInputs["listFixtureStudents"];
export type ListFixtureStudentsContractOutput =
  AdmissionsContractOutputs["listFixtureStudents"];
export type ListFixtureUniversitiesContractInput =
  AdmissionsContractInputs["listFixtureUniversities"];
export type ListFixtureUniversitiesContractOutput =
  AdmissionsContractOutputs["listFixtureUniversities"];

export type StudentId = z.infer<typeof studentIdSchema>;
export type StateCode = z.infer<typeof stateCodeSchema>;
